@ConfigurationProperties("p020.instancia")
public record InstanciaComs(int copia, Plaza plaza, Ambiente ambiente) {

    /** WS-SOLO-VDM-VA = 1 en MTY; WS-88-SOLO-VDM es VALUE 0, o sea verdadero fuera de MTY. */
    public boolean procesaTef() { return plaza != Plaza.MTY; }

    /** IF NOT WS-DH-HOSTNAME-PBA PERFORM 10200000-CHECA-VERSION. */
    public boolean validaVersion() { return ambiente != Ambiente.PBA; }
}

/** WS-S151-TIPO-PROC: P020 usa 33..37 (P010, la copia primaria, usa otro rango). */
static int tipoProcesoS151(int copia) {
    return switch (copia) {
        case 1 -> 33;
        case 2 -> 34;
        case 3 -> 35;
        case 4 -> 36;
        case 5 -> 37;
        default -> throw new IllegalStateException("Copia no soportada: " + copia);
    };
}

@Bean
ApplicationRunner inicioS151(InstanciaComs inst, RegistroS151Client s151) {
    return args -> {
        if (inst.modo() == Modo.LINEA) {                 // IF WS-88-TP-LINEA
            s151.inicia(tipoProcesoS151(inst.copia()));  // 50004100-S151-INICIO
        }
    };
}

