/** Actividades que atiende cada copia (catálogo en las líneas 17906-17914). */
public enum Actividad { COMS, ARCHIVO, B53, B54, B55, BATCH, LINEA, BASE, BAJA }

static Actividad actividadInicial(int copia) {
    return switch (copia) {
        case 1 -> Actividad.B53;       // MOVE 03 TO WKS-SIGUIENTE
        case 2 -> Actividad.COMS;      // 01
        case 3 -> Actividad.B54;       // 04
        case 4, 5 -> Actividad.ARCHIVO; // 02
        default -> throw new IllegalStateException("Copia no soportada: " + copia);
    };
}

@Bean
ApplicationRunner replicaInicial(InstanciaComs inst, ReplicaI11Service replica,
                                 TaskScheduler scheduler, P020Properties props) {
    return args -> {
        if (inst.modo() != Modo.LINEA || inst.copia() != 5) return;
        Duration espera = inst.ambiente() == Ambiente.PBA
                ? Duration.ZERO
                : props.esperaReplica();                    // p020.espera-replica: 1200s (WAIT(1200))
        scheduler.schedule(replica::genera, Instant.now().plus(espera));   // 50201400-I11-REPLICA
    };
}

@RestController
@RequestMapping("/admin/coms")
@RequiredArgsConstructor
public class ComsAdminController {      // sustituye a INTERRUPT-BY-HI (DECLARATIVES)

    private final InstanciaComs instancia;
    private final ComsGateway coms;     // 90000000-CALL-SMCOMS-DISABLE
    private final MensajesOperacion msg;

    /** TASKVALUE 3004: cualquier copia se deshabilita. */
    @PostMapping("/deshabilitar")
    public ResponseEntity<String> deshabilitar() {
        return ejecutaDisable();
    }

    /** TASKVALUE 3104: solo la copia 1 se deshabilita; en otras copias no hace nada. */
    @PostMapping("/deshabilitar-primaria")
    public ResponseEntity<String> deshabilitarPrimaria() {
        if (instancia.copia() != 1) {
            return ResponseEntity.ok("IGNORADO: COPIA " + instancia.copia());   // NEXT SENTENCE
        }
        return ejecutaDisable();
    }

    private ResponseEntity<String> ejecutaDisable() {
        msg.despliega(4);                                  // WS-NO-DISPLAY = 004
        boolean ok = coms.disable() == 1;                  // WS-COMS-RESULT = 1
        if (ok) msg.despliega(8);                          // WS-NO-DISPLAY = 008
        return ResponseEntity.ok(ok ? "DESHABILITADO" : "SIN CONFIRMACION");
    }
}

private final RegistroS151Client s151;     // REGISTRAS500 / LIB-S151L002R500
private final ProblemasLog problemas;      // I02-PROBLEMAS

/** TASKVALUE 3027: alterna el uso de S151. Solo en PBA y en modo línea. */
@PostMapping("/s151/alternar")
public ResponseEntity<String> alternaS151() {
    if (instancia.ambiente() != Ambiente.PBA || instancia.modo() != Modo.LINEA) {
        return ResponseEntity.ok("IGNORADO");                 // NEXT SENTENCE, sin mensaje
    }
    if (s151.activo()) {                                      // WS-88-SIUSA-S151
        s151.libera();                                        // CANCEL "REGISTRAS500"
        msg.despliega(42);
        return ResponseEntity.ok("S151 DESACTIVADO");
    }
    s151.carga();                                             // 70000000-LIB-S151L002R500
    msg.despliega(41);
    return ResponseEntity.ok("S151 ACTIVADO");
}

/** Rama ELSE final: cualquier TASKVALUE no reconocido se registra como no implementado. */
@ExceptionHandler(NoHandlerFoundException.class)
public ResponseEntity<String> noImplementado(HttpServletRequest req) {
    msg.despliega(5);
    problemas.escribe(">> FECHA MAQUINA: %s   HORA MAQUINA: %s HI # %s NO IMPLEMENTADO"
            .formatted(LocalDate.now(), LocalTime.now(), req.getRequestURI()));
    return ResponseEntity.status(HttpStatus.NOT_IMPLEMENTED).build();
}

/** 70000000-VAL-REG-POSTING: SORT S02-POSTING-T con INPUT/OUTPUT PROCEDURE. */
@Bean
Step ordenaPosting(JobRepository repo, PlatformTransactionManager tx,
                   ItemReader<PostingDetalle> postingEntrada,      // 70000000-IN-POST-SEC (I08-POSTING-I)
                   ItemWriter<PostingDetalle> postingSalida) {      // 70000000-OU-POST-SEC
    return new StepBuilder("ordenaPosting", repo)
            .<PostingDetalle, PostingDetalle>chunk(500, tx)
            .reader(new SortingItemReader<>(postingEntrada, ORDEN_S02))
            .writer(postingSalida)
            .build();
}

/** Llave S02 en el orden del SORT; todas DESCENDING. Importe como BigDecimal (9(14)V99). */
static final Comparator<PostingDetalle> ORDEN_S02 =
        Comparator.comparingInt(PostingDetalle::claveTransaccion)
                  .thenComparing(PostingDetalle::sucursal)
                  .thenComparing(PostingDetalle::contrato)      // String de 12 posiciones con ceros
                  .thenComparing(PostingDetalle::importe)
                  .thenComparingLong(PostingDetalle::secuencia)
                  .reversed();
